function.arguments:
{"command":"cd /tmp/models && python3 << 'EOF'
import numpy as np
import pickle

models = []

# Load all npz files
for i in range(1, 11):
    fname = f'model_{i:02d}.npz'
    try:
        d = np.load(fname, allow_pickle=True)
    except Exception as e:
        fname2 = f'model_{i:02d}.pkl'
        try:
            d = pickle.load(open(fname2, 'rb'))
        except Exception as e2:
            print(f"Failed to load {i}: {e}, {e2}")
            continue

    models.append((i, d['id'], d['val_accuracy']))
    print(f"sub_{i:02d}: id={d['id']}, val_accuracy={d['val_accuracy']}")

EOF
"}

